pub const fn repeat(&self, n: usize) -> Result<(Self, usize), LayoutError> {
    let padded = self.pad_to_align();
    if let Ok(repeated) = padded.repeat_packed(n) {
        Ok((repeated, padded.size()))
    } else {
        Err(LayoutError)
    }
}

pub const fn repeat_packed(&self, n: usize) -> Result<Self, LayoutError> {
    if let Some(size) = self.size.checked_mul(n) {
        // The safe constructor is called here to enforce the isize size limit.
        Layout::from_size_alignment(size, self.align)
    } else {
        Err(LayoutError)
    }
}

pub const fn pad_to_align(&self) -> Layout {
    // This cannot overflow. Quoting from the invariant of Layout:
    // > `size`, when rounded up to the nearest multiple of `align`,
    // > must not overflow isize (i.e., the rounded value must be
    // > less than or equal to `isize::MAX`)
    let new_size = self.size_rounded_up_to_custom_align(self.align);

    // SAFETY: padded size is guaranteed to not exceed `isize::MAX`.
    unsafe { Layout::from_size_align_unchecked(new_size, self.align()) }
}

const fn from_size_alignment(size: usize, align: Alignment) -> Result<Self, LayoutError> {
    if size > Self::max_size_for_align(align) {
        return Err(LayoutError);
    }

    // SAFETY: Layout::size invariants checked above.
    Ok(Layout { size, align })
}

const fn max_size_for_align(align: Alignment) -> usize {
    // (power-of-two implies align != 0.)

    // Rounded up size is:
    //   size_rounded_up = (size + align - 1) & !(align - 1);
    //
    // We know from above that align != 0. If adding (align - 1)
    // does not overflow, then rounding up will be fine.
    //
    // Conversely, &-masking with !(align - 1) will subtract off
    // only low-order-bits. Thus if overflow occurs with the sum,
    // the &-mask cannot subtract enough to undo that overflow.
    //
    // Above implies that checking for summation overflow is both
    // necessary and sufficient.

    // SAFETY: the maximum possible alignment is `isize::MAX + 1`,
    // so the subtraction cannot overflow.
    unsafe { unchecked_sub(isize::MAX as usize + 1, align.as_usize()) }
}

fn try_allocate_in(
    capacity: usize,
    init: AllocInit,
    alloc: A,
    elem_layout: Layout,
) -> Result<Self, TryReserveError> {
    // We avoid `unwrap_or_else` here because it bloats the amount of
    // LLVM IR generated.
    let layout = match layout_array(capacity, elem_layout) {
        Ok(layout) => layout,
        Err(_) => return Err(CapacityOverflow.into()),
    };

    // Don't allocate here because `Drop` will not deallocate when `capacity` is 0.
    if layout.size() == 0 {
        return Ok(Self::new_in(alloc, elem_layout.alignment()));
    }

    let result = match init {
        AllocInit::Uninitialized => alloc.allocate(layout),
        #[cfg(not(no_global_oom_handling))]
        AllocInit::Zeroed => alloc.allocate_zeroed(layout),
    };
    let ptr = match result {
        Ok(ptr) => ptr,
        Err(_) => return Err(AllocError { layout, non_exhaustive: () }.into()),
    };

    // Allocators currently return a `NonNull<[u8]>` whose length
    // matches the size requested. If that ever changes, the capacity
    // here should change to `ptr.len() / size_of::<T>()`.
    Ok(Self {
        ptr: Unique::from(ptr.cast()),
        cap: unsafe { Cap::new_unchecked(capacity) },
        alloc,
    })
}

const fn handle_error(e: TryReserveError) -> ! {
    match e.kind() {
        CapacityOverflow => capacity_overflow(),
        AllocError { layout, .. } => handle_alloc_error(layout),
    }
}

const fn layout_array(cap: usize, elem_layout: Layout) -> Result<Layout, TryReserveError> {
    // FIXME(const-hack) return to using `map` and `map_err` once `const_closures` is implemented
    match elem_layout.repeat(cap) {
        Ok((layout, _pad)) => Ok(layout),
        Err(_) => Err(CapacityOverflow.into()),
    }
}

fn alloc_impl_runtime(layout: Layout, zeroed: bool) -> Result<NonNull<[u8]>, AllocError> {
    match layout.size() {
        0 => Ok(NonNull::slice_from_raw_parts(layout.dangling(), 0)),
        // SAFETY: `layout` is non-zero in size,
        size => unsafe {
            let raw_ptr = if zeroed { alloc_zeroed(layout) } else { alloc(layout) };
            let ptr = NonNull::new(raw_ptr).ok_or(AllocError)?;
            Ok(NonNull::slice_from_raw_parts(ptr, size))
        },
    }
}

fn deallocate_impl_runtime(ptr: NonNull<u8>, layout: Layout) {
    if layout.size() != 0 {
        // SAFETY:
        // * We have checked that `layout` is non-zero in size.
        // * The caller is obligated to provide a layout that "fits", and in this case,
        //   "fit" always means a layout that is equal to the original, because our
        //   `allocate()`, `grow()`, and `shrink()` implementations never returns a larger
        //   allocation than requested.
        // * Other conditions must be upheld by the caller, as per `Allocator::deallocate()`'s
        //   safety documentation.
        unsafe { dealloc(ptr.as_ptr(), layout) }
    }
}

impl<Z> Zeroize for IterMut<'_, Z>
where
    Z: Zeroize,
{
    fn zeroize(&mut self) {
        for elem in self {
            elem.zeroize();
        }
    }
}

impl<Z, const N: usize> Zeroize for [Z; N]
where
    Z: Zeroize,
{
    fn zeroize(&mut self) {
        self.iter_mut().zeroize();
    }
}

fn volatile_write<T: Copy + Sized>(dst: &mut T, src: T) {
    unsafe { ptr::write_volatile(dst, src) }
}
